import { readFileSync, writeFileSync } from "node:fs";
const reference = JSON.parse(
  readFileSync("src/data/marinduque-reference.json", "utf8"),
);
const facilities = JSON.parse(readFileSync("src/data/facilities.json", "utf8"));
const sql = (value) => "'" + String(value).replaceAll("'", "''") + "'";
const lines = [
  "-- Generated by npm run seed:generate. Re-runnable: existing verified facilities are preserved.",
  "begin;",
];
for (const municipality of reference.municipalities) {
  lines.push(
    `insert into public.municipalities(name,psgc_code) values(${sql(municipality.name)},${sql(municipality.psgcCode)}) on conflict(name) do update set psgc_code=excluded.psgc_code;`,
  );
  for (const b of municipality.barangays)
    lines.push(
      `insert into public.barangays(psgc_code,name,municipality) values(${sql(b.psgcCode)},${sql(b.name)},${sql(municipality.name)}) on conflict(psgc_code) do update set name=excluded.name,municipality=excluded.municipality;`,
    );
}
for (const f of facilities)
  lines.push(
    `insert into public.facilities(id,municipality,payload) values(${sql(f.id)},${sql(f.municipality)},${sql(JSON.stringify(f))}::jsonb) on conflict(id) do nothing;`,
  );
lines.push("commit;", "");
writeFileSync("supabase/seed.sql", lines.join("\n"));
